<?php require __DIR__.'/includes/bootstrap.php';require_guest();$token=(string)($_GET['token']??$_POST['token']??'');$error='';$done=false;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$new=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm']??'');if(strlen($new)<12)$error='Password must be at least 12 characters.';elseif($new!==$confirm)$error='Password confirmation does not match.';else{$s=db()->prepare('SELECT id,user_id FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW() LIMIT 1');$s->execute([hash('sha256',$token)]);$r=$s->fetch();if(!$r)$error='This reset link is invalid, expired, or already used.';else{db()->beginTransaction();try{db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),$r['user_id']]);db()->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?')->execute([$r['id']]);db()->commit();$done=true;}catch(Throwable $e){db()->rollBack();throw $e;}}}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset password</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="panel auth"><h1>Reset password</h1><?php if($done):?><div class="alert success">Password reset complete.</div><a href="login.php">Login</a><?php else:if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><div class="field"><label>New password (12+ characters)</label><input type="password" name="password" minlength="12" required></div><div class="field"><label>Confirm password</label><input type="password" name="confirm" minlength="12" required></div><button>Reset password</button></form><?php endif;?></main></body></html>